SELECT YEAR(opened_date) AS opened_year, CASE WHEN region IN ('East', 'North') THEN 'core' ELSE 'other' END AS region_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(region))) AS region_values, SUM(CASE WHEN region = 'South' THEN 1 ELSE 0 END) AS south_count FROM stores WHERE UPPER(store_name) LIKE '%IAM%' AND (region <> 'North' OR store_name LIKE '%Rivers%') GROUP BY 1, 2 HAVING SUM(CASE WHEN region = 'South' THEN 1 ELSE 0 END) > 53 ORDER BY region_group ASC
